-- Align the manual anesthesia migration with the Prisma schema and query contract.
-- IDs remain generated by Prisma clients, matching the rest of the application schema.
ALTER TABLE "anesthesia_records"
ALTER COLUMN "id" DROP DEFAULT;

ALTER TABLE "anesthesia_observations"
ALTER COLUMN "id" DROP DEFAULT;

-- Recreate read-path indexes with the intended sort order for patient history and practitioner/procedure filters.
DROP INDEX IF EXISTS "anesthesia_records_org_patient_started_created_idx";
CREATE INDEX "anesthesia_records_org_patient_started_created_idx"
ON "anesthesia_records"("organization_id", "patient_id", "started_at" DESC NULLS LAST, "created_at" DESC, "id" ASC);

DROP INDEX IF EXISTS "anesthesia_records_org_responsible_started_idx";
CREATE INDEX "anesthesia_records_org_responsible_started_idx"
ON "anesthesia_records"("organization_id", "responsible_practitioner_membership_id", "started_at" DESC);

DROP INDEX IF EXISTS "anesthesia_records_org_procedure_started_idx";
CREATE INDEX "anesthesia_records_org_procedure_started_idx"
ON "anesthesia_records"("organization_id", "clinical_procedure_id", "started_at" DESC)
WHERE "clinical_procedure_id" IS NOT NULL;
